<script setup>
import {computed,ref,watch} from 'vue';
import {PLAY_GROUPS,playOverview} from '../core/play-overview.js';
import {formatMoney as money,MARKETS} from '../core/rules.js';
const props=defineProps({overview:Object,verification:Object,odds:Object});
defineEmits(['open','locate']);
const group=ref(''),market=ref(''),table=ref('plays'),status=ref(''),play=ref(''),ledger=ref(''),page=ref(1);
const entries=computed(()=>props.overview.rows.flatMap(r=>r.result?.entries||[]));
const stats=computed(()=>playOverview(entries.value,{group:group.value,market:market.value,verification:props.verification,odds:props.odds}));
const scopeName=computed(()=>`${market.value?market.value+'市场':'全部市场'} · ${PLAY_GROUPS.find(g=>g.id===group.value)?.name||'全部玩法'}`);
const records=computed(()=>stats.value.entries.filter(e=>(!status.value||e.status===status.value)&&(!play.value||`${e.playType}:${e.play}`===play.value)&&(!ledger.value||e.fileId===ledger.value)));
const pages=computed(()=>Math.max(1,Math.ceil(records.value.length/20)));
watch([group,market],()=>{play.value='';ledger.value='';page.value=1;});
watch([status,play,ledger],()=>page.value=1);watch(pages,value=>page.value=Math.min(page.value,value));
const balance=r=>r.netCents===null?'待结算':`${r.status==='trial'?'试算 · ':''}${r.netCents>0?'+':''}${money(r.netCents)}`;
const statusText=e=>({won:'中奖',lost:'未中',pending:'待结算',refund:'退本金'}[e.status]||e.status);
function filterRows(row){if(table.value==='plays'){play.value=play.value===row.id?'':row.id;ledger.value='';}else{ledger.value=ledger.value===row.id?'':row.id;play.value='';}}
</script>
<template>
 <section class="play-overview" aria-label="按玩法统计">
  <header class="play-heading"><div><h2>按玩法看全部账目</h2><p>先选玩法，再看具体投注和赔付。</p></div><label>市场<select v-model="market" aria-label="玩法统计市场"><option value="">全部市场</option><option v-for="m in MARKETS" :key="m" :value="m">{{m}}市场</option></select></label></header>
  <div class="play-categories" role="group" aria-label="玩法分类">
   <button :class="{selected:!group}" :aria-pressed="!group" @click="group=''" aria-label="玩法：全部"><span>全部玩法</span><strong>¥ {{money(stats.categories.reduce((n,g)=>n+g.stakeCents,0))}}</strong><small>{{entries.filter(e=>!market||e.market===market).length}} 笔</small></button>
   <template v-for="g in stats.categories" :key="g.id"><button v-if="g.id!=='other'||g.entryCount" :class="{selected:group===g.id}" :aria-pressed="group===g.id" :aria-label="'玩法：'+g.name" :title="g.description" @click="group=g.id"><span>{{g.name}}</span><strong>¥ {{money(g.stakeCents)}}</strong><small>{{g.ledgerCount}} 份账目 · {{g.entryCount}} 笔</small></button></template>
  </div>
  <div class="play-scope-heading"><h3>{{scopeName}}</h3><span>按投注金额从高到低</span></div>
  <div class="play-metrics" aria-label="当前玩法汇总"><div><small>已解析投注</small><strong>¥ {{money(stats.stakeCents)}}</strong><span>{{stats.ledgerCount}} 份账目 · {{stats.entryCount}} 笔</span></div><div><small>中奖投注</small><strong>¥ {{money(stats.winningStakeCents)}}</strong><span>{{stats.winEntries}} 笔 · {{stats.winCount}} 注</span></div><div><small>{{stats.pending?'已算赔付（未完成）':stats.status==='trial'?'赔付（试算）':'赔付'}}</small><strong>¥ {{money(stats.payoutCents)}}</strong><span>含退本金 {{money(stats.refundCents)}}</span></div><div><small>玩法净输赢（未含退水）</small><strong :class="{'profit-positive':stats.netCents>0,'profit-negative':stats.netCents<0}">{{balance(stats)}}</strong><span>赔付 − 已解析投注</span></div></div>
  <p v-if="stats.pending" class="play-notice">本范围 {{stats.pending}} 笔待结算；下方可筛选查看原因，净输赢暂不确定。</p>
  <p v-if="overview.issueCount" class="play-notice">全部账目还有 {{overview.issueCount}} 项原文问题，尚未计入玩法统计。请回到账目处理后查看完整金额。</p>
  <div class="panel play-table"><header><div class="play-table-switch" role="group" aria-label="玩法统计明细视角"><button :class="{selected:table==='plays'}" @click="table='plays'">具体玩法</button><button :class="{selected:table==='ledgers'}" @click="table='ledgers'">参与账目</button></div><small>点击名称筛选下方原文</small></header><div class="play-table-scroll"><table><thead><tr><th>{{table==='plays'?'玩法':'账目'}}</th><th>投注金额</th><th>中奖投注</th><th>中奖笔／注</th><th>赔付</th><th>玩法净输赢（未含退水）</th></tr></thead><tbody><tr v-for="r in stats[table]" :key="r.id" :class="{selected:(table==='plays'?play:ledger)===r.id}"><td><button class="text-button" @click="filterRows(r)">{{r.name}}</button><small>{{r.entryCount}} 笔<span v-if="table==='plays'"> · {{r.ledgerCount}} 份账目</span></small><button v-if="table==='ledgers'" class="text-button play-open" @click="$emit('open',r.id)">打开账目 ↗</button></td><td class="play-stake">{{money(r.stakeCents)}}</td><td>{{money(r.winningStakeCents)}}</td><td>{{r.winEntries}} / {{r.winCount}}</td><td>{{money(r.payoutCents)}}<small v-if="r.pending">{{r.pending}} 笔待结算</small><small v-else-if="r.status==='trial'">试算</small></td><td :class="{'profit-positive':r.netCents>0,'profit-negative':r.netCents<0}">{{balance(r)}}</td></tr><tr v-if="!stats.entryCount"><td colspan="6" class="play-empty">本范围暂无已解析投注。</td></tr></tbody></table></div></div>
  <div class="panel play-records"><header><h3>投注记录 <small>{{records.length}} 笔</small></h3><select v-model="status" aria-label="玩法记录状态"><option value="">全部状态</option><option value="won">只看中奖</option><option value="pending">待结算</option><option value="lost">未中奖</option><option value="refund">退本金</option></select><button v-if="play||ledger" class="text-button" @click="play='';ledger=''">清除名称筛选 ×</button></header>
   <details v-for="e in records.slice((page-1)*20,page*20)" :key="e.id"><summary><span class="play-record-title">{{e.fileName}} · {{e.market}} · {{e.play}}<small>{{e.raw}}</small></span><span :class="['play-status',e.status]">{{statusText(e)}}</span><span class="play-record-money">投注 {{money(e.stakeCents)}}<strong>{{e.payoutCents===null?'待结算':'赔付 '+money(e.payoutCents)}}</strong></span></summary><p v-if="e.drawDate">开奖 {{e.drawDate}} · {{e.issue}}期</p><p>{{e.note}}</p><p v-for="(t,i) in e.tiers" :key="i">{{t.count}}注 × {{money(t.unitPayoutCents)}}元（{{t.rate}}倍）＝ {{money(t.payoutCents)}}元</p><button class="text-button" @click="$emit('locate',e)">第{{e.line}}{{e.endLine>e.line?'–'+e.endLine:''}}行 · 定位原文 ↗</button></details>
   <p v-if="!records.length" class="play-empty">当前筛选下没有投注记录。</p><div class="pagination"><span>{{records.length}} 笔</span><button :disabled="page===1" @click="page--">上一页</button>{{page}} / {{pages}}<button :disabled="page===pages" @click="page++">下一页</button></div>
  </div><p class="play-footnote">退水在账目与每日玩家结算中单列，此处玩法净输赢未含退水。每笔按市场分别统计；三边投注计为三笔。中奖投注只计算命中的部分；赔付含退本金，未确认的开奖或赔率保留试算状态。</p>
 </section>
</template>
<style scoped>
.play-overview{margin:24px 0}.play-heading,.play-table header,.play-records header,.play-scope-heading{display:flex;align-items:center;gap:15px;justify-content:space-between}.play-heading h2{font-size:20px;margin:0}.play-heading p,.play-footnote{font-size:12px;color:#728474;line-height:1.8}.play-heading label{display:flex;gap:8px;align-items:center;white-space:nowrap;font-size:12px}.play-heading select,.play-records select{font-size:12px;padding:7px 9px}.play-categories{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin:16px 0 22px}.play-categories button{text-align:left;padding:13px 15px;border:1px solid #dbe5dd;border-radius:9px;background:#fff;color:#42664d}.play-categories button:hover{border-color:#81a98c}.play-categories button.selected{background:#edf6ef;border-color:#4d835c;box-shadow:inset 3px 0 #4d835c}.play-categories span{font-size:14px;font-weight:600}.play-categories strong{display:block;font-size:19px;margin:8px 0;font-variant-numeric:tabular-nums}.play-categories small{font-size:11px;color:#768c79}.play-scope-heading h3{font-size:16px}.play-scope-heading>span{font-size:11px;color:#7a8a7b}.play-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0}.play-metrics>div{padding:14px;border-left:2px solid #c5d9cb;background:#f1f6f2}.play-metrics small,.play-metrics span{display:block;font-size:11px;color:#758779}.play-metrics strong{display:block;font-size:20px;color:#315c40;margin:10px 0;font-variant-numeric:tabular-nums}.play-notice{font-size:12px;color:#966235;background:#fff5e8;padding:10px;border-radius:6px}.play-table,.play-records{padding:16px;margin-top:16px}.play-table header>small{font-size:11px;color:#82917f}.play-table-switch{display:flex;gap:6px}.play-table-switch button{font-size:12px;padding:7px 12px;border-radius:5px;color:#6d816e}.play-table-switch button.selected{background:#e8f2ea;color:#285d3c}.play-table-scroll{overflow:auto}.play-table table{width:100%;min-width:660px;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}.play-table td,.play-table th{text-align:right;padding:13px 9px;border-bottom:1px solid #ebf0e8}.play-table td:first-child,.play-table th:first-child{text-align:left}.play-table th{font-weight:400;color:#819279}.play-table small{display:block;color:#86967d;font-size:10px;margin-top:5px}.play-table tr.selected{background:#eff5ed}.play-table .play-stake{font-weight:600;font-size:16px}.play-open{margin-top:8px}.play-records header{justify-content:flex-start;flex-wrap:wrap}.play-records h3{font-size:15px;margin-right:auto}.play-records h3 small{font-size:11px;color:#83977e;font-weight:400;margin-left:7px}.play-records details{border-bottom:1px solid #e6ece1;font-size:12px}.play-records summary{display:flex;align-items:center;gap:14px;padding:14px 0;cursor:pointer}.play-record-title{flex:1;min-width:0;line-height:1.7}.play-record-title small{display:block;color:#778a74;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.play-status{padding:3px 6px;border-radius:4px;background:#eff2ed;color:#87907c;font-size:11px;white-space:nowrap}.play-status.won{background:#fff0ca;color:#95621d}.play-status.pending{background:#fff0e5;color:#a2613e}.play-record-money{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;color:#577358}.play-record-money strong{display:block;font-size:13px;margin-top:5px;color:#355c40}.play-records p{line-height:1.8;color:#73896c}.play-records details>.text-button{margin:8px 0 14px}.play-empty{padding:18px;text-align:center;color:#87977d;font-size:12px}.profit-positive,.play-metrics .profit-positive{color:#b45c42}.profit-negative,.play-metrics .profit-negative{color:#438064}@media(max-width:1000px){.play-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.play-categories{grid-template-columns:repeat(2,minmax(0,1fr))}.play-heading{align-items:flex-start}.play-heading h2{font-size:17px}.play-categories strong{font-size:17px}}
</style>
